// Turn one Gmail message into the intake's normal webhook fields, or drop it.
// One mailbox serves both environments: mail to <mailbox>+staging@... belongs to STAGING, everything else to production.
const STAGING = false;

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const h = m.headers ?? {};                                         // mailparser: lower-case key -> "Key: value" line
  const hv = k => String(h[k] ?? '').replace(/^[^:]*:\s*/, '').trim();
  const addrs = o => (o?.value ?? []).map(v => String(v.address ?? '').toLowerCase());

  const recipients = [...addrs(m.to), ...addrs(m.cc), hv('delivered-to').toLowerCase()];
  if (recipients.some(a => a.includes('+staging@')) !== STAGING) continue;   // the other environment's mail

  // Not an enquiry: robots, auto-replies, bulk mail.
  const sender = addrs(m.from)[0] ?? '';
  const auto = hv('auto-submitted');
  if (!sender
      || /^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounces?)[@+]/i.test(sender)
      || (auto && !/^no$/i.test(auto))
      || h['list-unsubscribe'] || h['list-id']
      || /^(bulk|list|junk|auto_reply)$/i.test(hv('precedence'))
      || h['x-autoreply'] || h['x-autorespond']) continue;

  // Only the new text: cut the quoted earlier message ("On ... wrote:", which Gmail may wrap onto two lines,
  // or an Outlook "Original Message"/"From:" block) and the signature ("-- "), then drop any "> " lines.
  let text = String(m.text ?? '').replace(/\r\n/g, '\n');
  const cut = text.search(/^(On [^\n]*(\n[^\n]*)?wrote:\s*$|-{2,} ?Original Message|From: .+$|-- ?$)/m);
  if (cut > 0) text = text.slice(0, cut);
  text = text.split('\n').filter(l => !/^\s*>/.test(l)).join('\n').trim().slice(0, 5000);
  if (!text) continue;

  out.push({ json: {
    email: sender,
    name: m.from?.value?.[0]?.name || null,
    subject: m.subject ?? null,
    message: text,
    channel: 'email',
    gmail_message_id: m.id,
    gmail_thread_id: m.threadId
  }});
}
return out;
